<template>
  <div class="page-renderer">
    

    <!-- Loading -->
    <div v-if="loading" class="state-msg">Loading...</div>

    <!-- Error -->
    <div v-else-if="error" class="state-msg error">{{ error }}</div>

    <!-- Page Content -->
    <div v-else-if="page">
      <h1 class="page-title">{{ page.title }}</h1>

      <!-- Sections (recursive) -->
      <SectionNode
        v-for="section in page.sections"
        :key="section.id"
        :node="section"
      />

      <!-- Media -->
      <div v-if="page.media && page.media.length" class="media-section">
        <h3>Media</h3>
        <div class="media-grid">
          <template v-for="item in page.media" :key="item.id">
            <img
              v-if="item.type === 'image'"
              :src="mediaUrl(item.file_path)"
              :alt="`media-${item.id}`"
              class="media-image"
            />
            <a
              v-else
              :href="mediaUrl(item.file_path)"
              target="_blank"
              class="media-file"
            >
              📄 {{ item.file_path.split('/').pop() }}
            </a>
          </template>
        </div>
      </div>
    </div>
  </div>
  
</template>

<script setup>
import { ref, onMounted, defineComponent, h } from 'vue'
import axios from 'axios'
  import { useRoute} from 'vue-router';
const api = axios.create({ baseURL: 'https://bushman.ink/api/v2/' })
    const route = useRoute();
const page    = ref(null)
const loading = ref(true)
const error   = ref(null)

// ── Recursive section renderer ────────────────────────────────────────────────
const SectionNode = defineComponent({
  name: 'SectionNode',
  props: { node: { type: Object, required: true } },
  setup(props) {
    return () => {
      const { node } = props

      // Build children VNodes (recursive)
      const childNodes = (node.children || []).map(child =>
        h(SectionNode, { key: child.id, node: child })
      )

      // Inner content (text/html) + child sections
      const innerContent = []
  if (node.content) {
  if (node.content.text) {
    innerContent.push(node.content.text)
  }
}
      innerContent.push(...childNodes)

      // Merge attributes from API (class, style, etc.)
const attrs = {
  class: ['section-node', node.type, node.attributes?.class].filter(Boolean).join(' '),
  style: node.attributes?.style ?? '',
}
      return h('div', attrs, innerContent)
    }
  },
})

// ── Media URL helper ──────────────────────────────────────────────────────────
const APP_URL = 'https://bushman.ink'

const mediaUrl = (path) => {
  if (!path) return ''
  return /^https?:\/\//i.test(path) ? path : `${APP_URL}/${path}`
}

// ── Data fetching ─────────────────────────────────────────────────────────────
const getPage = async () => {
  try {
    loading.value = true
    const response = await api.get(`pages/${route.params.id}`)
    page.value = response.data
  } catch (e) {
    error.value = e?.response?.data?.message || e.message || 'Failed to load page.'
  } finally {
    loading.value = false
  }
}

onMounted(getPage)
</script>

<style scoped>
.page-renderer { padding: 1.5rem; font-family: sans-serif; }

.state-msg      { padding: 1rem; color: #555; }
.state-msg.error{ color: #c0392b; }

.page-title     { font-size: 1.8rem; margin-bottom: 1rem; }

/* Section nodes inherit their class/style from the API */
.section-node   { padding: 0.25rem; }

/* Media */
.media-section  { margin-top: 2rem; }
.media-grid     { display: flex; flex-wrap: wrap; gap: 1rem; margin-top: 0.5rem; }
.media-image    { max-width: 240px; border-radius: 6px; object-fit: cover; }
.media-file     { display: inline-flex; align-items: center; gap: .4rem;
                  padding: .5rem 1rem; background: #f0f0f0;
                  border-radius: 6px; text-decoration: none; color: #333; }
.media-file:hover { background: #e0e0e0; }
</style>